def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    red_bear_patches = image_patch.find("bear in a red coat")
    white_bear_patches = image_patch.find("bear in a white coat")

    if not red_bear_patches or not white_bear_patches:
        return image_patch

    touching = [rb for rb in red_bear_patches for wb in white_bear_patches if distance(rb, wb) < min(rb.width, rb.height, wb.width, wb.height)]

    if touching:
        return touching[0]

    return red_bear_patches[0]

